CREATE COLUMN TABLE "TEST_AP"."ORTS" ("RateDate" LONGDATE CS_LONGDATE NOT NULL , "Currency" NVARCHAR(3) NOT NULL , "Rate" DECIMAL(21,6) CS_FIXED, "DataSource" NVARCHAR(1) DEFAULT 'N', "UserSign" SMALLINT CS_INT, "ReportType" NVARCHAR(1) DEFAULT 'S' NOT NULL , PRIMARY KEY ("RateDate", "Currency", "ReportType")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "ORTS_DATE" ON "TEST_AP"."ORTS" ( "RateDate" ASC )